package com.example.qldetai.feature.evaluation.domain;
import com.example.qldetai.feature.identity.domain.User; import com.example.qldetai.feature.project.domain.ProjectAssignment; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import lombok.*;
@Entity @Table(name="result_versions") @Getter @Setter @NoArgsConstructor public class ResultVersion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assignment_id") private ProjectAssignment assignment; @Column(name="version_no",nullable=false) private int versionNo; @Column(name="final_score",nullable=false,precision=5,scale=2) private BigDecimal finalScore; @Column(name="calculation_rule",nullable=false) private String calculationRule="MEAN_COMPONENTS_V1"; @Enumerated(EnumType.STRING) @Column(nullable=false) private ResultStatus status=ResultStatus.FINALIZED; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="finalized_by") private User finalizedBy; @Column(name="finalized_at",nullable=false) private LocalDateTime finalizedAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="published_by") private User publishedBy; @Column(name="published_at") private LocalDateTime publishedAt; }
